package stateroot

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"math/bits"
	"os"
	"strings"
	"testing"
)

// THE SHARED VECTORS. This package's implementation is independent of the Infrix runtime's (pkg/rootaccum) on purpose; ONE file of vectors, generated by the runtime
// repository, pins them to each other. This test holds this implementation to its copy of that file and pins the copy's SHA-256, so neither copy can be edited
// alone: change the runtime's implementation and its vectors change, the runtime's tests demand the new file be committed there, and this pin fails here until the
// new file is copied over and the pin is updated deliberately, in the same commit as whatever made this implementation agree with it.
//
// vectorsSHA256 is over the file's bytes as committed: LF line endings only. .gitattributes pins the file `text eol=lf`, so a Windows checkout with core.autocrlf=true cannot
// rewrite it; a checkout that did (its bytes carry a carriage return, so they hash to another value than every other repository's copy) is refused by name below and never
// normalised around.
const vectorsSHA256 = "d978b0eb62bdcfa38963fa93df00b192431766b72d7735ae3ca435eab2901ef9"

const vectorsPath = "testdata/state-root-vectors.json"

type vectorLeaf struct {
	Height         uint64 `json:"height"`
	Root           string `json:"root"`
	Consumer       string `json:"consumer,omitempty"`
	ConsumerDigest string `json:"consumerDigest,omitempty"`
	LeafHash       string `json:"leafHash"`
}

type vectorProof struct {
	Index uint64   `json:"index"`
	Path  []string `json:"path"`
}

type vectorTree struct {
	Size   uint64        `json:"size"`
	Sealed string        `json:"sealed"`
	Proofs []vectorProof `json:"proofs"`
}

type vectorConsistency struct {
	First    uint64   `json:"first"`
	Second   uint64   `json:"second"`
	FirstMth string   `json:"firstMth"`
	Path     []string `json:"path"`
}

type vectorAnchor struct {
	Roots       []string `json:"roots"`
	FirstHeight uint64   `json:"firstHeight"`
	LastHeight  uint64   `json:"lastHeight"`
}

type vectorDocCase struct {
	Name           string                  `json:"name"`
	Document       json.RawMessage         `json:"document,omitempty"`
	BundleRoot     string                  `json:"bundleRoot"`
	ConsumerID     string                  `json:"consumerId,omitempty"`
	Anchors        map[string]vectorAnchor `json:"anchors,omitempty"`
	AnchorError    string                  `json:"anchorError,omitempty"`
	NoReader       bool                    `json:"noReader,omitempty"`
	Verdict        string                  `json:"verdict"`
	DetailContains []string                `json:"detailContains"`
}

// vectorCheckpoint is the checkpoint of a tree of Size leaves (ledger L1647): the compact range (the perfect subtrees of the binary decomposition of Size, left to right) and the sealed
// root it folds to.
type vectorCheckpoint struct {
	Size    uint64   `json:"size"`
	Compact []string `json:"compact"`
	Sealed  string   `json:"sealed"`
}

type vectorFile struct {
	SealDomain     string              `json:"sealDomain"`
	ConsumerDomain string              `json:"consumerDomain"`
	Leaves         []vectorLeaf        `json:"leaves"`
	Trees          []vectorTree        `json:"trees"`
	Consistency    []vectorConsistency `json:"consistency"`
	Checkpoints    []vectorCheckpoint  `json:"checkpoints"`
	Documents      []vectorDocCase     `json:"documents"`
}

// vectorBytesProblem says what is wrong with the bytes of the vector file as this checkout holds them, or nil. The file is pinned by SHA-256 over its LF bytes (the same pin as
// every other repository's copy), so a carriage return anywhere in it means the checkout rewrote it, and the cure is the attribute, not a hash taken over a normalised copy.
func vectorBytesProblem(raw []byte) error {
	if bytes.Contains(raw, []byte("\r")) {
		return errors.New("testdata/state-root-vectors.json carries a carriage return: this checkout rewrote its line endings (core.autocrlf=true does that to any file .gitattributes does not pin), and the SHA-256 this package pins is over the LF bytes the file is committed with: pin it in .gitattributes with `stateroot/testdata/*.json text eol=lf` and check the file out again")
	}
	return nil
}

func loadVectors(t *testing.T) vectorFile {
	t.Helper()
	raw, err := os.ReadFile(vectorsPath)
	if err != nil {
		t.Fatal(err)
	}
	if err := vectorBytesProblem(raw); err != nil {
		t.Fatal(err)
	}
	sum := sha256.Sum256(raw)
	if got := hex.EncodeToString(sum[:]); got != vectorsSHA256 {
		t.Fatalf("testdata/state-root-vectors.json has SHA-256 %s, but this package pins %s: the vectors are generated by the Infrix runtime's pkg/rootaccum and copied here whole; if they changed on purpose, copy the new file and update the pin in the same commit as the change that makes this implementation agree", got, vectorsSHA256)
	}
	var vf vectorFile
	if err := json.Unmarshal(raw, &vf); err != nil {
		t.Fatal(err)
	}
	return vf
}

func mustDecode(t *testing.T, s string) [32]byte {
	t.Helper()
	h, err := decode32(s)
	if err != nil {
		t.Fatal(err)
	}
	return h
}

func mustPath(t *testing.T, in []string) [][32]byte {
	t.Helper()
	p, err := decodePath(in)
	if err != nil {
		t.Fatal(err)
	}
	return p
}

// Every leaf of the vectors hashes to the leaf hash the runtime computed, a consumer leaf commits to its consumer's digest, and a root-change leaf and a consumer
// leaf of the same height and root hash differently (two kinds that cannot be mistaken for each other).
func TestEveryLeafHashAndEveryConsumerDigestOfTheVectorsIsReproduced(t *testing.T) {
	vf := loadVectors(t)
	if vf.SealDomain != SealDomain || vf.ConsumerDomain != ConsumerDomain {
		t.Fatalf("the vectors use domains %q and %q, this package %q and %q", vf.SealDomain, vf.ConsumerDomain, SealDomain, ConsumerDomain)
	}
	consumers := 0
	for i, l := range vf.Leaves {
		root := mustDecode(t, l.Root)
		if got := hex.EncodeToString(func() []byte { h := leafHash(l.Height, root, l.Consumer); return h[:] }()); got != l.LeafHash {
			t.Fatalf("leaf %d hashes to %s, the vectors say %s", i, got, l.LeafHash)
		}
		if l.Consumer != "" {
			consumers++
			d := ConsumerDigest(l.Consumer)
			if hex.EncodeToString(d[:]) != l.ConsumerDigest {
				t.Fatalf("leaf %d: the digest of %q is %x, the vectors say %s", i, l.Consumer, d, l.ConsumerDigest)
			}
			if leafHash(l.Height, root, l.Consumer) == leafHash(l.Height, root, "") {
				t.Fatalf("leaf %d: a consumer leaf and a root-change leaf of the same height and root hash alike", i)
			}
		}
	}
	if consumers != 10 {
		t.Fatalf("%d consumer leaves in the vectors, want the 10 the runtime generates", consumers)
	}
}

func TestEveryAuditPathOfEveryTreeSizeToFortyComputesTheSealTheVectorsName(t *testing.T) {
	vf := loadVectors(t)
	if len(vf.Trees) != 40 {
		t.Fatalf("%d trees in the vectors, want every size 1..40", len(vf.Trees))
	}
	proofs := 0
	for _, tr := range vf.Trees {
		sealed := mustDecode(t, tr.Sealed)
		if uint64(len(tr.Proofs)) != tr.Size {
			t.Fatalf("size %d has %d proofs, want one per leaf", tr.Size, len(tr.Proofs))
		}
		for _, vp := range tr.Proofs {
			leaf := vf.Leaves[vp.Index]
			root := mustDecode(t, leaf.Root)
			path := mustPath(t, vp.Path)
			got, err := SealedRootOf(vp.Index, tr.Size, leaf.Height, root, leaf.Consumer, path)
			if err != nil {
				t.Fatalf("size %d leaf %d: %v", tr.Size, vp.Index, err)
			}
			if got != sealed {
				t.Fatalf("size %d leaf %d computes %x, the vectors say %s", tr.Size, vp.Index, got[:8], tr.Sealed)
			}
			// a tampered copy of the same proof must not compute the same seal
			if len(path) > 0 {
				bad := append([][32]byte(nil), path...)
				bad[0][0] ^= 1
				if g, err := SealedRootOf(vp.Index, tr.Size, leaf.Height, root, leaf.Consumer, bad); err == nil && g == sealed {
					t.Fatalf("size %d leaf %d: a flipped sibling computes the same seal", tr.Size, vp.Index)
				}
			}
			// a consumer leaf proves only for its own consumer
			if leaf.Consumer != "" {
				if g, err := SealedRootOf(vp.Index, tr.Size, leaf.Height, root, leaf.Consumer+"x", path); err == nil && g == sealed {
					t.Fatalf("size %d leaf %d: another consumer computes the same seal", tr.Size, vp.Index)
				}
				if g, err := SealedRootOf(vp.Index, tr.Size, leaf.Height, root, "", path); err == nil && g == sealed {
					t.Fatalf("size %d leaf %d: the leaf proves with its consumer removed", tr.Size, vp.Index)
				}
			}
			proofs++
		}
	}
	if proofs != 40*41/2 {
		t.Fatalf("%d proofs checked, want %d (every leaf of every size)", proofs, 40*41/2)
	}
}

// Every pair of sizes 1 <= first <= second <= 40 has a consistency proof in the vectors; each verifies, computes the second tree's seal the vectors name, and
// fails when any element is flipped, dropped or added, when the first hash is not the first tree's, and when the sizes are not the proof's.
func TestEveryConsistencyProofOfEveryPairOfSizesToFortyVerifies(t *testing.T) {
	vf := loadVectors(t)
	if len(vf.Consistency) != 40*41/2 {
		t.Fatalf("%d consistency vectors, want %d (every pair 1 <= first <= second <= 40)", len(vf.Consistency), 40*41/2)
	}
	for _, c := range vf.Consistency {
		firstSealed := mustDecode(t, vf.Trees[c.First-1].Sealed)
		secondSealed := mustDecode(t, vf.Trees[c.Second-1].Sealed)
		firstMth := mustDecode(t, c.FirstMth)
		path := mustPath(t, c.Path)
		if seal(c.First, firstMth) != firstSealed {
			t.Fatalf("(%d,%d): the vectors' first hash does not seal to the first tree's sealed root", c.First, c.Second)
		}
		secondMth, err := VerifyConsistency(c.First, c.Second, firstMth, path)
		if err != nil {
			t.Fatalf("(%d,%d): %v", c.First, c.Second, err)
		}
		if seal(c.Second, secondMth) != secondSealed {
			t.Fatalf("(%d,%d): the proof computes a second tree whose seal is not the one the vectors name", c.First, c.Second)
		}
		if len(path) > 0 {
			flipped := append([][32]byte(nil), path...)
			flipped[len(flipped)-1][5] ^= 0x80
			if sm, err := VerifyConsistency(c.First, c.Second, firstMth, flipped); err == nil && seal(c.Second, sm) == secondSealed {
				t.Fatalf("(%d,%d): a flipped last element still proves", c.First, c.Second)
			}
			if sm, err := VerifyConsistency(c.First, c.Second, firstMth, path[1:]); err == nil && seal(c.Second, sm) == secondSealed {
				t.Fatalf("(%d,%d): a dropped first element still proves", c.First, c.Second)
			}
		}
		extra := append(append([][32]byte(nil), path...), [32]byte{9})
		if sm, err := VerifyConsistency(c.First, c.Second, firstMth, extra); err == nil && seal(c.Second, sm) == secondSealed {
			t.Fatalf("(%d,%d): an extra element still proves", c.First, c.Second)
		}
		wrongFirst := firstMth
		wrongFirst[0] ^= 1
		// (for a first tree whose size is a power of two the first hash IS the first element of the proof, so the proof is self-consistent with it; what refuses it
		// is the seal of the second tree it computes, which is the comparison the caller makes)
		if sm, err := VerifyConsistency(c.First, c.Second, wrongFirst, path); err == nil && seal(c.Second, sm) == secondSealed {
			t.Fatalf("(%d,%d): a first hash that is not the first tree's still proves the second tree's seal", c.First, c.Second)
		}
		if c.Second < 40 {
			if sm, err := VerifyConsistency(c.First, c.Second+1, firstMth, path); err == nil && seal(c.Second+1, sm) == mustDecode(t, vf.Trees[c.Second].Sealed) {
				t.Fatalf("(%d,%d): the proof verifies for a larger second tree", c.First, c.Second)
			}
		}
	}
	// a first tree larger than the second is no prefix of it, and an empty first tree proves nothing
	if _, err := VerifyConsistency(5, 4, [32]byte{}, nil); err == nil {
		t.Error("a first tree larger than the second verified")
	}
	if _, err := VerifyConsistency(0, 4, [32]byte{}, nil); err == nil {
		t.Error("an empty first tree verified")
	}
}

type vectorReader struct {
	anchors map[string]AnchorEntry
	err     error
}

func (r vectorReader) AnchorAt(_ context.Context, tx string) (AnchorEntry, error) {
	if r.err != nil {
		return AnchorEntry{}, r.err
	}
	e, ok := r.anchors[tx]
	if !ok {
		return AnchorEntry{}, errors.New("no such transaction")
	}
	return e, nil
}

func TestEveryDocumentCaseOfTheVectorsGetsItsVerdict(t *testing.T) {
	vf := loadVectors(t)
	if len(vf.Documents) < 40 {
		t.Fatalf("%d document cases in the vectors", len(vf.Documents))
	}
	verdicts := map[string]int{}
	for _, c := range vf.Documents {
		var doc *Document
		if len(c.Document) > 0 {
			doc = &Document{}
			if err := json.Unmarshal(c.Document, doc); err != nil {
				t.Fatalf("%s: %v", c.Name, err)
			}
		}
		bundleRoot := mustDecode(t, c.BundleRoot)
		var reader AnchorReader
		if !c.NoReader {
			vr := vectorReader{anchors: map[string]AnchorEntry{}}
			for tx, a := range c.Anchors {
				e := AnchorEntry{FirstHeight: a.FirstHeight, LastHeight: a.LastHeight}
				for _, r := range a.Roots {
					e.Roots = append(e.Roots, mustDecode(t, r))
				}
				vr.anchors[tx] = e
			}
			if c.AnchorError != "" {
				vr.err = errors.New(c.AnchorError)
			}
			reader = vr
		}
		res := Check(context.Background(), doc, bundleRoot, c.ConsumerID, reader)
		if string(res.Verdict) != c.Verdict {
			t.Fatalf("%s: verdict %s (%s), want %s", c.Name, res.Verdict, res.Detail, c.Verdict)
		}
		for _, want := range c.DetailContains {
			if !strings.Contains(res.Detail, want) {
				t.Fatalf("%s: detail %q does not contain %q", c.Name, res.Detail, want)
			}
		}
		verdicts[c.Verdict]++
	}
	if verdicts["pass"] == 0 || verdicts["skip"] == 0 || verdicts["fail"] == 0 {
		t.Fatalf("the vectors do not exercise every outcome: %v", verdicts)
	}
}

// passingCase returns the vectors' passing delayed-anchor document with its bundle root, consumer id and reader, to mutate one thing at a time.
func passingCase(t *testing.T) (*Document, [32]byte, string, vectorReader) {
	t.Helper()
	vf := loadVectors(t)
	for _, c := range vf.Documents {
		if c.Name != "a proven leaf recorded in the gap of a delayed anchor passes" {
			continue
		}
		doc := &Document{}
		if err := json.Unmarshal(c.Document, doc); err != nil {
			t.Fatal(err)
		}
		vr := vectorReader{anchors: map[string]AnchorEntry{}}
		for tx, a := range c.Anchors {
			e := AnchorEntry{FirstHeight: a.FirstHeight, LastHeight: a.LastHeight}
			for _, r := range a.Roots {
				e.Roots = append(e.Roots, mustDecode(t, r))
			}
			vr.anchors[tx] = e
		}
		return doc, mustDecode(t, c.BundleRoot), c.ConsumerID, vr
	}
	t.Fatal("the vectors have no passing delayed-anchor case")
	return nil, [32]byte{}, "", vectorReader{}
}

func copyDoc(d *Document) *Document {
	c := *d
	if d.Prior != nil {
		p := *d.Prior
		c.Prior = &p
	}
	return &c
}

// The reader refuses what it does not read, whatever else is true of the document: a version-1 document that carries a consumer and a valid proof, and a status it
// does not know, are skips and never a pass.
func TestADocumentOfAVersionOrStatusTheVerifierDoesNotReadIsNeverAPass(t *testing.T) {
	doc, root, consumer, reader := passingCase(t)
	if res := Check(context.Background(), doc, root, consumer, reader); res.Verdict != VerdictPass {
		t.Fatalf("premise: the case does not pass: %+v", res)
	}
	v1 := copyDoc(doc)
	v1.Version = documentVersionV1
	if res := Check(context.Background(), v1, root, consumer, reader); res.Verdict != VerdictSkip || !strings.Contains(res.Detail, "no consumer recorded") {
		t.Errorf("a version 1 document carrying a consumer and a valid proof: %+v", res)
	}
	odd := copyDoc(doc)
	odd.Status = Status("bogus")
	if res := Check(context.Background(), odd, root, consumer, reader); res.Verdict != VerdictSkip || !strings.Contains(res.Detail, "does not read") {
		t.Errorf("a status the verifier does not know: %+v", res)
	}
}

// The prior's sealed root must be the seal of the size and tree hash the document gives for it: a root L0 DOES list, from another history, beside the real size and
// hash of this one proves nothing, and the consistency proof alone cannot see it (it speaks of the size and hash, not of what L0 listed).
func TestAPriorWhoseListedRootIsNotTheSealOfItsSizeAndHashIsRefused(t *testing.T) {
	doc, root, consumer, reader := passingCase(t)
	other := [32]byte{0xfe, 0xed}
	priorTx := doc.Prior.Anchor.TxHash
	e := reader.anchors[priorTx]
	e.Roots = append(e.Roots, other)
	reader.anchors[priorTx] = e
	forged := copyDoc(doc)
	forged.Prior.AccumulatorRoot = hex.EncodeToString(other[:])
	res := Check(context.Background(), forged, root, consumer, reader)
	if res.Verdict != VerdictFail || !strings.Contains(res.Detail, "not shown to be a prefix") {
		t.Fatalf("a prior root that is not the seal of its size and hash: %+v", res)
	}
}

// A first tree larger than the second is no prefix of it, however the proof is shaped (a first tree of a power-of-two size with its own hash as the whole proof would
// otherwise verify against nothing).
func TestAFirstTreeLargerThanTheSecondIsNeverAPrefixOfItForAnyProofShape(t *testing.T) {
	h := [32]byte{1}
	for _, c := range [][2]uint64{{2, 1}, {4, 3}, {8, 5}, {4, 1}, {3, 2}} {
		if _, err := VerifyConsistency(c[0], c[1], h, nil); err == nil {
			t.Errorf("(%d,%d) with an empty proof verified", c[0], c[1])
		}
		if _, err := VerifyConsistency(c[0], c[1], h, [][32]byte{{2}}); err == nil {
			t.Errorf("(%d,%d) with a one-element proof verified", c[0], c[1])
		}
	}
}

// A proof with an element too many is refused by the verification itself, not only by the seal that would then not match.
func TestAConsistencyProofWithAnExtraElementIsRefusedByTheVerificationItself(t *testing.T) {
	vf := loadVectors(t)
	checked := 0
	for _, c := range vf.Consistency {
		if c.First == c.Second {
			continue
		}
		extra := append(mustPath(t, c.Path), [32]byte{9})
		if _, err := VerifyConsistency(c.First, c.Second, mustDecode(t, c.FirstMth), extra); err == nil {
			t.Fatalf("(%d,%d): a proof with an extra element verified", c.First, c.Second)
		}
		// and one with its last element missing: the proof is not used up, so it proves nothing about the second tree
		if full := mustPath(t, c.Path); len(full) >= 2 {
			if _, err := VerifyConsistency(c.First, c.Second, mustDecode(t, c.FirstMth), full[:len(full)-1]); err == nil {
				t.Fatalf("(%d,%d): a proof missing its last element verified", c.First, c.Second)
			}
		}
		checked++
	}
	if checked == 0 {
		t.Fatal("no consistency vector was checked")
	}
}

// ---- the checkpoint statement (ledger L1647) ----
//
// An unavailable document may carry the node's statement that it checkpointed its root history. The statement proves nothing about the bundle (a skip at best, never a
// pass); it can be FALSE, and a false one is refused. Every vector of the file's `checkpoints` section and every field of the statement is held here.

func checkpointOf(c vectorCheckpoint) Checkpoint {
	return Checkpoint{Size: c.Size, SealedRoot: c.Sealed, Compact: append([]string(nil), c.Compact...)}
}

func flipHex(t *testing.T, h string) string {
	t.Helper()
	b := mustDecode(t, h)
	b[0] ^= 1
	return hex.EncodeToString(b[:])
}

func mustRefuse(t *testing.T, what string, c Checkpoint, want string) {
	t.Helper()
	err := c.Verify()
	if err == nil {
		t.Fatalf("%s: the statement was accepted", what)
	}
	if want != "" && !strings.Contains(err.Error(), want) {
		t.Fatalf("%s: refused with %q, want it to contain %q", what, err.Error(), want)
	}
}

func TestEveryCheckpointOfTheVectorsFoldsToTheSealTheVectorsNameAndEveryTamperOfItIsRefused(t *testing.T) {
	vf := loadVectors(t)
	if len(vf.Checkpoints) != 40 {
		t.Fatalf("%d checkpoints in the vectors, want one per tree size 1..40", len(vf.Checkpoints))
	}
	for _, c := range vf.Checkpoints {
		if len(c.Compact) != bits.OnesCount64(c.Size) {
			t.Fatalf("size %d: %d compact entries, want one per one bit of the size (%d)", c.Size, len(c.Compact), bits.OnesCount64(c.Size))
		}
		if c.Sealed != vf.Trees[c.Size-1].Sealed {
			t.Fatalf("size %d: the checkpoint names seal %s, the tree of that size is sealed %s", c.Size, c.Sealed, vf.Trees[c.Size-1].Sealed)
		}
		ck := checkpointOf(c)
		if err := ck.Verify(); err != nil {
			t.Fatalf("size %d: %v", c.Size, err)
		}
		up := checkpointOf(c)
		up.Size++
		mustRefuse(t, fmt.Sprintf("size %d: the range for the next larger size", c.Size), up, "")
		down := checkpointOf(c)
		down.Size--
		mustRefuse(t, fmt.Sprintf("size %d: the range for the next smaller size", c.Size), down, "")
		sealed := checkpointOf(c)
		sealed.SealedRoot = flipHex(t, c.Sealed)
		mustRefuse(t, fmt.Sprintf("size %d: another sealed root", c.Size), sealed, "the compact range does not fold to the sealed root")
		for i := range c.Compact {
			flipped := checkpointOf(c)
			flipped.Compact[i] = flipHex(t, flipped.Compact[i])
			mustRefuse(t, fmt.Sprintf("size %d: entry %d flipped", c.Size, i), flipped, "the compact range does not fold to the sealed root")
			dropped := checkpointOf(c)
			dropped.Compact = append(append([]string(nil), c.Compact[:i]...), c.Compact[i+1:]...)
			mustRefuse(t, fmt.Sprintf("size %d: entry %d dropped", c.Size, i), dropped, fmt.Sprintf("a tree of %d leaves has a compact range of %d subtrees, not %d", c.Size, len(c.Compact), len(c.Compact)-1))
			bad := checkpointOf(c)
			bad.Compact[i] = "not-hex"
			mustRefuse(t, fmt.Sprintf("size %d: entry %d malformed", c.Size, i), bad, fmt.Sprintf("compact[%d]", i))
		}
		extra := checkpointOf(c)
		extra.Compact = append(extra.Compact, hex.EncodeToString(bytes.Repeat([]byte{9}, 32)))
		mustRefuse(t, fmt.Sprintf("size %d: an extra entry", c.Size), extra, fmt.Sprintf("the compact range has more entries than the %d leaves it covers have subtrees", c.Size))
		none := checkpointOf(c)
		none.Compact = nil
		mustRefuse(t, fmt.Sprintf("size %d: no entries", c.Size), none, fmt.Sprintf("a tree of %d leaves has a compact range of %d subtrees, not 0", c.Size, len(c.Compact)))
		if len(c.Compact) >= 2 && c.Compact[0] != c.Compact[1] {
			swapped := checkpointOf(c)
			swapped.Compact[0], swapped.Compact[1] = swapped.Compact[1], swapped.Compact[0]
			mustRefuse(t, fmt.Sprintf("size %d: the two largest subtrees swapped", c.Size), swapped, "the compact range does not fold to the sealed root")
		}
	}
	// a range with the right number of entries for ANOTHER size is not this size's: sizes 3 and 5 both have two subtrees
	var three, five vectorCheckpoint
	for _, c := range vf.Checkpoints {
		switch c.Size {
		case 3:
			three = c
		case 5:
			five = c
		}
	}
	mustRefuse(t, "the range of 3 offered for 5", Checkpoint{Size: 5, SealedRoot: five.Sealed, Compact: three.Compact}, "the compact range does not fold to the sealed root")
	mustRefuse(t, "the range of 5 offered for 3", Checkpoint{Size: 3, SealedRoot: three.Sealed, Compact: five.Compact}, "the compact range does not fold to the sealed root")
}

func TestACheckpointWhoseSizeSealedRootOrEntriesAreMalformedIsRefusedByName(t *testing.T) {
	vf := loadVectors(t)
	var c21 vectorCheckpoint
	for _, c := range vf.Checkpoints {
		if c.Size == 21 {
			c21 = c
		}
	}
	good := checkpointOf(c21)
	if err := good.Verify(); err != nil {
		t.Fatal(err)
	}
	zero := good
	zero.Size = 0
	mustRefuse(t, "a checkpoint that seals no leaves", zero, "the checkpoint seals no leaves")
	for _, bad := range []string{"not-hex", "", good.SealedRoot[2:], good.SealedRoot[1:], good.SealedRoot + "00"} {
		c := checkpointOf(c21)
		c.SealedRoot = bad
		mustRefuse(t, fmt.Sprintf("sealed root %q", bad), c, "sealedRoot: ")
	}
	c := checkpointOf(c21)
	c.SealedRoot = good.SealedRoot[2:]
	mustRefuse(t, "a sealed root of 31 bytes", c, "sealedRoot: 31 bytes, want 32")
	c = checkpointOf(c21)
	c.Compact[2] = c.Compact[2][2:]
	mustRefuse(t, "an entry of 31 bytes", c, "compact[2]: 31 bytes, want 32")
	c = checkpointOf(c21)
	c.Compact[2] = c.Compact[2][1:]
	mustRefuse(t, "an odd-length entry", c, "compact[2]: ")
	if _, err := hex.DecodeString(c.Compact[2]); err == nil {
		t.Fatal("premise: an odd-length entry decodes")
	}
}

// a document whose statement cannot be read into the types the node writes it with never reaches the check: a size that is not a whole number, a negative one, a string, an overflowing one, a
// statement that is not an object
func TestAStatementThatDoesNotDecodeIntoTheNodesTypesIsNotADocument(t *testing.T) {
	for _, statement := range []string{`{"size":1.5}`, `{"size":-1}`, `{"size":"21"}`, `{"size":1e30}`, `{"size":18446744073709551616}`, `{"lastHeight":-3}`, `{"compact":"abcd"}`, `{"compact":[1]}`, `{"anchor":"x"}`, `0`, `false`, `"x"`, `[]`} {
		raw := `{"version":"infrix-state-root-proof-v2","status":"unavailable","stateRoot":"` + strings.Repeat("00", 32) + `","checkpoint":` + statement + `}`
		var d Document
		if err := json.Unmarshal([]byte(raw), &d); err == nil {
			t.Errorf("a checkpoint %s decoded into a Document: %+v", statement, d.Checkpoint)
		}
	}
	for _, statement := range []string{`{}`, `null`, `{"size":null}`} {
		raw := `{"version":"infrix-state-root-proof-v2","status":"unavailable","stateRoot":"` + strings.Repeat("00", 32) + `","checkpoint":` + statement + `}`
		var d Document
		if err := json.Unmarshal([]byte(raw), &d); err != nil {
			t.Errorf("a checkpoint %s did not decode: %v", statement, err)
		}
	}
}

func vectorCase(t *testing.T, name string) vectorDocCase {
	t.Helper()
	for _, c := range loadVectors(t).Documents {
		if c.Name == name {
			return c
		}
	}
	t.Fatalf("the vectors have no case %q", name)
	return vectorDocCase{}
}

func entriesOf(t *testing.T, anchors map[string]vectorAnchor) map[string]AnchorEntry {
	t.Helper()
	out := map[string]AnchorEntry{}
	for tx, a := range anchors {
		e := AnchorEntry{FirstHeight: a.FirstHeight, LastHeight: a.LastHeight}
		for _, r := range a.Roots {
			e.Roots = append(e.Roots, mustDecode(t, r))
		}
		out[tx] = e
	}
	return out
}

func readerOfCase(t *testing.T, c vectorDocCase) AnchorReader {
	t.Helper()
	if c.NoReader {
		return nil
	}
	vr := vectorReader{anchors: entriesOf(t, c.Anchors)}
	if c.AnchorError != "" {
		vr.err = errors.New(c.AnchorError)
	}
	return vr
}

// docOf is the case's document with one thing changed, decoded the way a verifier is handed it.
func docOf(t *testing.T, c vectorDocCase, edit func(m map[string]any)) *Document {
	t.Helper()
	var m map[string]any
	if err := json.Unmarshal(c.Document, &m); err != nil {
		t.Fatal(err)
	}
	edit(m)
	b, err := json.Marshal(m)
	if err != nil {
		t.Fatal(err)
	}
	d := &Document{}
	if err := json.Unmarshal(b, d); err != nil {
		t.Fatal(err)
	}
	return d
}

func ckm(m map[string]any) map[string]any { return m["checkpoint"].(map[string]any) }

func confirmedCase(t *testing.T) vectorDocCase {
	return vectorCase(t, "an unavailable proof whose checkpoint L0 confirms is a skip saying so")
}

func checkOf(t *testing.T, c vectorDocCase, d *Document, reader AnchorReader) Result {
	t.Helper()
	return Check(context.Background(), d, mustDecode(t, c.BundleRoot), c.ConsumerID, reader)
}

func wantResult(t *testing.T, what string, got Result, verdict Verdict, contains ...string) {
	t.Helper()
	if got.Verdict != verdict {
		t.Fatalf("%s: verdict %s (%s), want %s", what, got.Verdict, got.Detail, verdict)
	}
	for _, w := range contains {
		if !strings.Contains(got.Detail, w) {
			t.Fatalf("%s: detail %q does not contain %q", what, got.Detail, w)
		}
	}
}

func TestADocumentThatStatesATrueCheckpointIsASkipAndNeverAPassForEveryCheckpointSizeOfTheVectors(t *testing.T) {
	vf := loadVectors(t)
	base := confirmedCase(t)
	for _, c := range vf.Checkpoints {
		doc := docOf(t, base, func(m map[string]any) {
			k := ckm(m)
			k["size"] = c.Size
			k["sealedRoot"] = c.Sealed
			compact := make([]any, len(c.Compact))
			for i, h := range c.Compact {
				compact[i] = h
			}
			k["compact"] = compact
		})
		l0 := vectorReader{anchors: map[string]AnchorEntry{"cc33": {Roots: [][32]byte{{1}, mustDecode(t, c.Sealed)}, FirstHeight: 150, LastHeight: 160}}}
		wantResult(t, fmt.Sprintf("size %d confirmed", c.Size), checkOf(t, base, doc, l0), VerdictSkip, fmt.Sprintf("checkpointed at leaf %d ", c.Size), "L0 lists that seal in anchor transaction cc33")
		wantResult(t, fmt.Sprintf("size %d offline", c.Size), checkOf(t, base, doc, nil), VerdictSkip, "no L0 endpoint was supplied")
		unlisted := vectorReader{anchors: map[string]AnchorEntry{"cc33": {Roots: [][32]byte{{1}}}}}
		wantResult(t, fmt.Sprintf("size %d unlisted", c.Size), checkOf(t, base, doc, unlisted), VerdictFail, "never anchored")
	}
}

func TestEveryFieldOfACheckpointStatementIsHeldSizeSealedRootCompactLastHeightReasonAndAnchor(t *testing.T) {
	c := confirmedCase(t)
	reader := readerOfCase(t, c)
	noop := func(m map[string]any) {}
	wantResult(t, "premise", checkOf(t, c, docOf(t, c, noop), reader), VerdictSkip,
		"L0 lists that seal in anchor transaction cc33", "no leaf is held for this bundle", "checkpointed at leaf 21 (canonical height 160)", "folds to sealed root 55fc35a95aeeccab...")

	// the node's own words (last height, reason) are reported, never judged: the verdict holds and the detail carries what the document says
	wantResult(t, "moved", checkOf(t, c, docOf(t, c, func(m map[string]any) { ckm(m)["lastHeight"] = 999; m["reason"] = "another reason" }), reader), VerdictSkip, "another reason", "canonical height 999")
	wantResult(t, "no height", checkOf(t, c, docOf(t, c, func(m map[string]any) { delete(ckm(m), "lastHeight") }), reader), VerdictSkip, "canonical height 0)")
	wantResult(t, "no reason", checkOf(t, c, docOf(t, c, func(m map[string]any) { delete(m, "reason") }), reader), VerdictSkip, "state root: ; it states")

	// the size
	for _, size := range []float64{22, 20, 0, 1} {
		got := checkOf(t, c, docOf(t, c, func(m map[string]any) { ckm(m)["size"] = size }), reader)
		wantResult(t, fmt.Sprintf("size %v", size), got, VerdictFail, fmt.Sprintf("checkpointed its root history at leaf %v, and the statement is false", size))
	}
	// the sealed root
	for _, sealed := range []string{strings.Repeat("09", 32), "zz", ""} {
		got := checkOf(t, c, docOf(t, c, func(m map[string]any) { ckm(m)["sealedRoot"] = sealed }), reader)
		wantResult(t, fmt.Sprintf("sealedRoot %q", sealed), got, VerdictFail, "the statement is false")
	}
	wantResult(t, "no sealed root", checkOf(t, c, docOf(t, c, func(m map[string]any) { delete(ckm(m), "sealedRoot") }), reader), VerdictFail, "the statement is false: sealedRoot: 0 bytes, want 32")
	// the compact range, entry by entry
	for i := 0; i < 3; i++ {
		flipped := checkOf(t, c, docOf(t, c, func(m map[string]any) {
			cs := ckm(m)["compact"].([]any)
			cs[i] = flipHex(t, cs[i].(string))
		}), reader)
		wantResult(t, fmt.Sprintf("compact[%d] flipped", i), flipped, VerdictFail, "the compact range does not fold to the sealed root")
		dropped := checkOf(t, c, docOf(t, c, func(m map[string]any) {
			cs := ckm(m)["compact"].([]any)
			ckm(m)["compact"] = append(append([]any(nil), cs[:i]...), cs[i+1:]...)
		}), reader)
		wantResult(t, fmt.Sprintf("compact[%d] dropped", i), dropped, VerdictFail, "the statement is false: a tree of 21 leaves has a compact range of 3 subtrees, not 2")
	}
	wantResult(t, "an extra entry", checkOf(t, c, docOf(t, c, func(m map[string]any) {
		ckm(m)["compact"] = append(ckm(m)["compact"].([]any), strings.Repeat("08", 32))
	}), reader), VerdictFail, "more entries than the 21 leaves it covers have subtrees")
	wantResult(t, "no range", checkOf(t, c, docOf(t, c, func(m map[string]any) { delete(ckm(m), "compact") }), reader), VerdictFail, "a compact range of 3 subtrees, not 0")

	// the anchor: absent or empty is unconfirmed, a transaction L0 does not have or cannot read is refused, a seal it does not list is refused; the account is a locator only
	for name, edit := range map[string]func(m map[string]any){
		"absent":  func(m map[string]any) { delete(ckm(m), "anchor") },
		"empty":   func(m map[string]any) { ckm(m)["anchor"] = map[string]any{} },
		"no hash": func(m map[string]any) { ckm(m)["anchor"] = map[string]any{"txHash": "", "account": "acc://x"} },
	} {
		wantResult(t, "anchor "+name, checkOf(t, c, docOf(t, c, edit), reader), VerdictSkip, "names no L0 anchor for that seal, so it is unconfirmed")
	}
	wantResult(t, "an unknown transaction", checkOf(t, c, docOf(t, c, func(m map[string]any) { ckm(m)["anchor"].(map[string]any)["txHash"] = "dead" }), reader), VerdictFail,
		"could not read the checkpoint's anchor from L0: no such transaction")
	down := vectorReader{err: errors.New("connection refused"), anchors: entriesOf(t, c.Anchors)}
	wantResult(t, "L0 down", checkOf(t, c, docOf(t, c, noop), down), VerdictFail, "could not read the checkpoint's anchor from L0: connection refused")
	other := vectorReader{anchors: map[string]AnchorEntry{"cc33": {Roots: [][32]byte{{4}}, FirstHeight: 150, LastHeight: 160}}}
	wantResult(t, "another seal", checkOf(t, c, docOf(t, c, noop), other), VerdictFail,
		"sealed root 55fc35a95aeeccab... is not listed in the L0 anchor entry of transaction cc33: the node never anchored it")
	wantResult(t, "another account", checkOf(t, c, docOf(t, c, func(m map[string]any) { ckm(m)["anchor"].(map[string]any)["account"] = "acc://elsewhere.acme/state" }), reader), VerdictSkip, "L0 lists that seal")
	// the roots alone are enough to confirm a seal: an entry with no window still confirms it
	rootsOnly := vectorReader{anchors: map[string]AnchorEntry{"cc33": {Roots: entriesOf(t, c.Anchors)["cc33"].Roots}}}
	wantResult(t, "no window", checkOf(t, c, docOf(t, c, noop), rootsOnly), VerdictSkip, "L0 lists that seal")
}

func TestTheCheckpointIsReadOnlyFromAnUnavailableDocumentOfTheVersionThisVerifierReadsAsTheRuntimeReadsIt(t *testing.T) {
	c := confirmedCase(t)
	reader := readerOfCase(t, c)
	falsified := func(edit func(m map[string]any)) *Document {
		return docOf(t, c, func(m map[string]any) {
			cs := ckm(m)["compact"].([]any)
			cs[0] = flipHex(t, cs[0].(string))
			edit(m)
		})
	}
	// a version it does not read is never looked into, whatever its status or its statement says
	wantResult(t, "v1", checkOf(t, c, falsified(func(m map[string]any) { m["version"] = documentVersionV1 }), reader), VerdictSkip, "version 1")
	wantResult(t, "v9", checkOf(t, c, falsified(func(m map[string]any) { m["version"] = "infrix-state-root-proof-v9" }), reader), VerdictSkip, "does not read")
	wantResult(t, "no version", checkOf(t, c, falsified(func(m map[string]any) { delete(m, "version") }), reader), VerdictSkip, "does not read")
	// a document that is not unavailable never has its statement judged: a proven one is judged as a proof, an awaiting one as awaiting
	wantResult(t, "awaiting", checkOf(t, c, falsified(func(m map[string]any) { m["status"] = "awaiting_anchor" }), reader), VerdictSkip, "unchecked until the next anchor")
	wantResult(t, "bogus status", checkOf(t, c, falsified(func(m map[string]any) { m["status"] = "bogus" }), reader), VerdictSkip, "does not read")
	p := vectorCase(t, "a proven leaf recorded in the gap of a delayed anchor passes")
	proven := docOf(t, p, func(m map[string]any) { m["checkpoint"] = map[string]any{"size": 0} })
	wantResult(t, "proven", checkOf(t, p, proven, readerOfCase(t, p)), VerdictPass)
	// no statement, an explicit null one: the plain unavailable skip; an empty one is judged and false
	plain := "the node could not prove the bundle's state root: no leaf is held for this bundle"
	for name, edit := range map[string]func(m map[string]any){
		"absent": func(m map[string]any) { delete(m, "checkpoint") },
		"null":   func(m map[string]any) { m["checkpoint"] = nil },
	} {
		got := checkOf(t, c, docOf(t, c, edit), reader)
		wantResult(t, "statement "+name, got, VerdictSkip, plain)
		if got.Detail != plain {
			t.Fatalf("statement %s: detail %q, want exactly %q", name, got.Detail, plain)
		}
	}
	wantResult(t, "an empty statement", checkOf(t, c, docOf(t, c, func(m map[string]any) { m["checkpoint"] = map[string]any{} }), reader), VerdictFail, "the statement is false: the checkpoint seals no leaves")
	// the bundle's own root and consumer are not read for a statement: it proves nothing about the bundle
	got := Check(context.Background(), docOf(t, c, func(m map[string]any) {}), [32]byte{}, "", reader)
	wantResult(t, "an anonymous bundle", got, VerdictSkip, "L0 lists that seal")
}

// THE FIXTURE IS CHECKED OUT AS IT IS COMMITTED. A Windows checkout with core.autocrlf=true rewrites every text file .gitattributes does not pin, and the vector file hashes to another
// value then (7578024e... instead of the pin d978b0eb...: the same bytes with CRLF endings), so the pin would fail, or, worse, be satisfied only by a hash taken over a normalised copy.
func TestAVectorFileThatCarriesACarriageReturnIsRefusedNamingGitattributes(t *testing.T) {
	raw, err := os.ReadFile(vectorsPath)
	if err != nil {
		t.Fatal(err)
	}
	if err := vectorBytesProblem(raw); err != nil {
		t.Fatalf("the committed vector file is refused: %v", err)
	}
	if sum := sha256.Sum256(raw); hex.EncodeToString(sum[:]) != vectorsSHA256 {
		t.Fatalf("premise: the vector bytes hash to %x, not the pin %s", sum, vectorsSHA256)
	}
	crlf := bytes.ReplaceAll(raw, []byte("\n"), []byte("\r\n"))
	lone := bytes.Replace(raw, []byte("\n"), []byte("\r"), 1)
	if sum := sha256.Sum256(crlf); hex.EncodeToString(sum[:]) == vectorsSHA256 {
		t.Fatal("premise: the CRLF form of the file hashes to the pin")
	}
	for name, rewritten := range map[string][]byte{"CRLF": crlf, "a lone CR": lone, "a CR at the very end": append(append([]byte(nil), raw...), '\r')} {
		err := vectorBytesProblem(rewritten)
		if err == nil {
			t.Fatalf("%s: a file that carries a carriage return was accepted", name)
		}
		for _, want := range []string{"carriage return", "any file .gitattributes does not pin", "pin it in .gitattributes with `stateroot/testdata/*.json text eol=lf` and check the file out again"} {
			if !strings.Contains(err.Error(), want) {
				t.Fatalf("%s: the refusal %q does not name %q", name, err.Error(), want)
			}
		}
	}
}

// pinsVectorsToLF reports whether a .gitattributes pins the stateroot fixtures to LF: a line of its own (not a comment, not another path, not another setting).
func pinsVectorsToLF(attributes string) bool {
	for _, line := range strings.Split(attributes, "\n") {
		if strings.TrimRight(line, "\r") == "stateroot/testdata/*.json text eol=lf" {
			return true
		}
	}
	return false
}

func TestTheRepositoryPinsTheVectorFileToLFInGitattributes(t *testing.T) {
	raw, err := os.ReadFile("../.gitattributes")
	if err != nil {
		t.Fatal(err)
	}
	if !pinsVectorsToLF(string(raw)) {
		t.Fatalf(".gitattributes does not pin the stateroot fixtures to LF: add the line `stateroot/testdata/*.json text eol=lf` (the vectors are pinned by SHA-256 over their LF bytes and core.autocrlf=true rewrites any file it does not pin)")
	}
	for name, attributes := range map[string]string{
		"empty":             "",
		"a comment":         "# stateroot/testdata/*.json text eol=lf\n",
		"another path":      "credverify/testdata/*.json text eol=lf\n",
		"another setting":   "stateroot/testdata/*.json text eol=crlf\n",
		"no text attribute": "stateroot/testdata/*.json eol=lf\n",
		"binary":            "stateroot/testdata/*.json -text\n",
		"a longer line":     "stateroot/testdata/*.json text eol=lf -diff\n",
	} {
		if pinsVectorsToLF(attributes) {
			t.Errorf("%s: %q was read as a pin", name, attributes)
		}
	}
	for name, attributes := range map[string]string{
		"LF":           "x text\nstateroot/testdata/*.json text eol=lf\ny text\n",
		"CRLF":         "x text\r\nstateroot/testdata/*.json text eol=lf\r\ny text\r\n",
		"the only one": "stateroot/testdata/*.json text eol=lf",
	} {
		if !pinsVectorsToLF(attributes) {
			t.Errorf("%s: %q was not read as a pin", name, attributes)
		}
	}
}

// Every status and every version a document can carry is read in the runtime's order, the version first: a version 1 document and a version this verifier does not read are skips
// whatever their status or their statement says, and the detail names the version (the status never gets to speak).
func TestEveryStatusAndEveryVersionIsReadInTheRuntimesOrderTheVersionFirst(t *testing.T) {
	checkpointed := confirmedCase(t)
	proven := vectorCase(t, "a proven leaf recorded in the gap of a delayed anchor passes")
	for _, status := range []string{"proven", "awaiting_anchor", "unavailable", "bogus"} {
		for version, want := range map[string]string{documentVersionV1: "version 1", "infrix-state-root-proof-v9": "does not read", "": "does not read"} {
			base := checkpointed
			if status == "proven" {
				base = proven
			}
			doc := docOf(t, base, func(m map[string]any) {
				m["status"] = status
				if version == "" {
					delete(m, "version")
				} else {
					m["version"] = version
				}
			})
			wantResult(t, fmt.Sprintf("%s %q", status, version), checkOf(t, base, doc, readerOfCase(t, base)), VerdictSkip, want)
		}
	}
}
